// Chess batch solver for the 5-Chess level (6.4), ported from public/chess63.html.
// The original page's logic, apart from: element lookups are scoped to `root`, the paste
// listener / timers are removed on destroy(), pasted links / the phone paste box go through the
// app's image loader, and every answer comes from Stockfish (the CSV answer book is gone, 2026-11-24)
// through the engine shared with the Chess module (chess/chessEngine.js).
import { extractImageFromPaste, extractImageSource, dragHasLink, warmImageHosts, loadImageSource, isInternalDrag } from '../../utils/image.js';
import { kingInCheck, startEngine as startSharedEngine, stopEngineListener, askEngine as askSharedEngine, cancelSearch, legalSan, SUPERSEDED } from '../chess/chessEngine.js';

/**
 * @param {HTMLElement} root  element holding the Chess63 markup
 * @param {{ onSolved?: (lines: string[]) => void }} opts  lines = "Ans N : move" for COPY ALL
 * @returns {{ loadSource(src, target?), destroy() }}
 */
export function mountChess63(root, { onSolved } = {}) {
  let destroyed = false;
  const NB = 5;

  const SHOWN = {
    K: '♔', Q: '♕', R: '♖', B: '♗', N: '♘', P: '♙',
    k: '♚', q: '♛', r: '♜', b: '♝', n: '♞', p: '♟'
  };
  const CYCLE = ['', 'P', 'N', 'B', 'R', 'Q', 'K', 'p', 'n', 'b', 'r', 'q', 'k'];
  const $ = id => root.querySelector('#' + id);

  // Application State for 5 Bombs
  const boards = {
    white: Array.from({ length: NB }, () => Array(64).fill('')),
    black: Array.from({ length: NB }, () => Array(64).fill('')),
    merged: Array.from({ length: NB }, () => Array(64).fill(''))
  };
  const conflicts = Array.from({ length: NB }, () => new Set());
  // Each bomb asks for White's OR Black's move, so both are solved and shown side by side
  const blankAns = () => ({ san: '', uci: '', ok: false });
  const answers = { w: Array.from({ length: NB }, blankAns), b: Array.from({ length: NB }, blankAns) };
  const picked = Array(NB).fill(null); // the side last clicked (copied) for each bomb — COPY ALL uses it
  const SIDE_NAME = { w: 'White', b: 'Black' };
  const SIDE_ICON = { w: '♔', b: '♚' };
  let activeBomb = 0;

  function copyText(text) {
    try { navigator.clipboard.writeText(text); } catch (e) {}
  }
  function toast(msg) {
    const t = $('toast');
    t.textContent = msg;
    t.classList.add('show');
    setTimeout(() => t.classList.remove('show'), 1800);
  }

  function loadImg(file) {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = e => {
        const img = new Image();
        img.onload = () => resolve(img);
        img.onerror = reject;
        img.src = e.target.result;
      };
      reader.onerror = reject;
      reader.readAsDataURL(file);
    });
  }

  // ===== CV BEGIN =====
  const TEMPLATE_SIZE = 32;
  const LEGACY_WHITE = {
    p: { h: 0.721, w: 0.548, cells: '' },
    b: { h: 0.879, w: 0.733, cells: '' },
    n: { h: 0.863, w: 0.726, cells: '' },
    q: { h: 0.905, w: 0.935, cells: '' },
    k: { h: 0.904, w: 0.904, cells: '' },
    r: { h: 0.815, w: 0.740, cells: '' }
  };
  // Per-colour templates learned from real screenshots (multi-scale). Black glyphs are drawn smaller than white ones,
  // so each colour has its own bank. h/w = bbox size as a fraction of the whole square.
  const NEW_TEMPLATES = {
    black: { r: { h: 0.631, w: 0.558, cells: '' }, n: { h: 0.656, w: 0.55, cells: '' }, k: { h: 0.684, w: 0.649, cells: '' }, p: { h: 0.558, w: 0.383, cells: '' }, b: { h: 0.66, w: 0.542, cells: '' }, q: { h: 0.711, w: 0.724, cells: '' } },
    white: { p: { h: 0.587, w: 0.437, cells: '' }, b: { h: 0.709, w: 0.594, cells: '' }, n: { h: 0.687, w: 0.582, cells: '' }, q: { h: 0.727, w: 0.748, cells: '' }, k: { h: 0.736, w: 0.715, cells: '' }, r: { h: 0.654, w: 0.585, cells: '' } }
  };
  function decodeBank(def, sizeScale) {
    const out = {};
    for (const t in def) {
      out[t] = {
        h: def[t].h * sizeScale, w: def[t].w * sizeScale,
        cells: Float32Array.from(def[t].cells.padEnd(TEMPLATE_SIZE * TEMPLATE_SIZE, '0'), d => Number(d) / 9)
      };
    }
    return out;
  }
  // legacy white templates were measured against the inset square (~0.833 of the cell)
  const BANKS = {
    white: [decodeBank(NEW_TEMPLATES.white, 1), decodeBank(LEGACY_WHITE, 0.833)],
    black: [decodeBank(NEW_TEMPLATES.black, 1)]
  };
  // ================= VISION CORE (scale-robust) =================
  const LIGHT_SQUARE = [200, 176, 138];
  const DARK_SQUARE = [122, 90, 58];
  const SEG = [DARK_SQUARE[0]-LIGHT_SQUARE[0], DARK_SQUARE[1]-LIGHT_SQUARE[1], DARK_SQUARE[2]-LIGHT_SQUARE[2]];
  const SEG_L2 = SEG[0]*SEG[0] + SEG[1]*SEG[1] + SEG[2]*SEG[2];
  const FG_DIST = 40;       // pixel is "piece" if this far from the light<->dark square colour line
  const LAMBDA = 0.3;       // weight of the size-vs-template penalty
  const rnd = v => Math.floor(v + 0.5);

  // Distance from an RGB pixel to the segment LIGHT_SQUARE..DARK_SQUARE.
  // A sliver of a neighbouring square or a blurred grid line lies ON this segment -> never counts as a piece.
  function segDist(r, g, b) {
    const px = r - LIGHT_SQUARE[0], py = g - LIGHT_SQUARE[1], pz = b - LIGHT_SQUARE[2];
    let t = (px*SEG[0] + py*SEG[1] + pz*SEG[2]) / SEG_L2;
    t = t < 0 ? 0 : t > 1 ? 1 : t;
    const dx = px - t*SEG[0], dy = py - t*SEG[1], dz = pz - t*SEG[2];
    return Math.sqrt(dx*dx + dy*dy + dz*dz);
  }

  function findRuns(counts, thr, minLen, gap) {
    const out = [];
    let start = -1, last = -1;
    for (let i = 0; i < counts.length; i++) {
      if (counts[i] >= thr) {
        if (start < 0) start = i;
        last = i;
      } else if (start >= 0 && i - last > gap) {
        out.push([start, last + 1]);
        start = -1;
      }
    }
    if (start >= 0) out.push([start, last + 1]);
    return out.filter(r => r[1] - r[0] >= minLen);
  }

  // Finds every chessboard in an RGBA image (any layout / scale), returned in reading order.
  // rect (optional) = {x0,y0,x1,y1} restricts the search.
  function findBoards(data, W, H, rect) {
    const x0 = rect ? rect.x0 : 0, y0 = rect ? rect.y0 : 0;
    const x1 = rect ? rect.x1 : W, y1 = rect ? rect.y1 : H;
    const rw = x1 - x0, rh = y1 - y0;
    const m = new Uint8Array(rw * rh);
    const rowC = new Int32Array(rh), colC = new Int32Array(rw);
    for (let y = 0; y < rh; y++) {
      for (let x = 0; x < rw; x++) {
        const i = ((y0 + y) * W + x0 + x) * 4;
        const r = data[i], g = data[i+1], b = data[i+2];
        // on the light<->dark colour line (includes blended pixels at square edges / after resizing)
        if (segDist(r, g, b) < 22) { m[y*rw + x] = 1; rowC[y]++; colC[x]++; }
      }
    }
    const maxOf = a => { let v = 0; for (const n of a) if (n > v) v = n; return v; };
    const minSide = Math.max(30, Math.floor(Math.min(rw, rh) * 0.12));
    const rr = findRuns(rowC, maxOf(rowC) * 0.2, minSide, 3);
    const cr = findRuns(colC, maxOf(colC) * 0.2, minSide, 3);
    const boards = [];
    for (const [r0, r1] of rr) {
      for (const [c0, c1] of cr) {
        const sr = new Int32Array(r1 - r0), sc = new Int32Array(c1 - c0);
        let total = 0;
        for (let y = r0; y < r1; y++) for (let x = c0; x < c1; x++) {
          if (m[y*rw + x]) { sr[y-r0]++; sc[x-c0]++; total++; }
        }
        if (total < 0.075 * (r1-r0) * (c1-c0)) continue;     // e.g. the KNOBS module
        const mr = maxOf(sr) * 0.25, mc = maxOf(sc) * 0.25;
        let ya = -1, yb = -1, xa = -1, xb = -1;
        for (let i = 0; i < sr.length; i++) if (sr[i] >= mr) { if (ya < 0) ya = i; yb = i; }
        for (let i = 0; i < sc.length; i++) if (sc[i] >= mc) { if (xa < 0) xa = i; xb = i; }
        const w = xb - xa + 1, h = yb - ya + 1;
        if (w < minSide || h < minSide) continue;
        boards.push({ x: x0 + c0 + xa, y: y0 + r0 + ya, w, h });
      }
    }
    return boards;
  }

  // Foreground (piece) mask of one square, inset so grid lines / neighbours are excluded.
  function squareMask(data, W, board, row, col) {
    const cw = board.w / 8, ch = board.h / 8;
    const mg = Math.max(1, rnd(Math.min(cw, ch) * 0.08));
    const l = rnd(board.x + col*cw) + mg, r = rnd(board.x + (col+1)*cw) - mg;
    const t = rnd(board.y + row*ch) + mg, b = rnd(board.y + (row+1)*ch) - mg;
    const w = r - l, h = b - t;
    if (w < 3 || h < 3) return null;
    let mask = new Uint8Array(w * h);
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const i = ((t + y) * W + l + x) * 4;
        if (segDist(data[i], data[i+1], data[i+2]) > FG_DIST) mask[y*w + x] = 1;
      }
    }
    // drop isolated single pixels
    const clean = new Uint8Array(w * h);
    let count = 0;
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        if (!mask[y*w + x]) continue;
        let nb = 0;
        for (let dy = -1; dy <= 1; dy++) for (let dx = -1; dx <= 1; dx++) {
          if (!dx && !dy) continue;
          const yy = y + dy, xx = x + dx;
          if (yy >= 0 && yy < h && xx >= 0 && xx < w && mask[yy*w + xx]) nb++;
        }
        if (nb > 0) { clean[y*w + x] = 1; count++; }
      }
    }
    return { mask: clean, w, h, count, cw, ch };
  }

  // 32x32 shape signature (cropped to bbox) + bbox size relative to the CELL (not the inset area).
  function buildFeature(sq) {
    const { mask, w, h, cw, ch } = sq;
    let left = w, right = -1, top = h, bottom = -1;
    for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) {
      if (!mask[y*w + x]) continue;
      if (x < left) left = x; if (x > right) right = x;
      if (y < top) top = y;   if (y > bottom) bottom = y;
    }
    if (right < 0) return null;
    const bw = right - left + 1, bh = bottom - top + 1;
    const cells = new Float32Array(TEMPLATE_SIZE * TEMPLATE_SIZE);
    for (let fy = 0; fy < TEMPLATE_SIZE; fy++) {
      const y0 = top + Math.floor(fy * bh / TEMPLATE_SIZE);
      const y1 = Math.max(y0 + 1, top + Math.floor((fy + 1) * bh / TEMPLATE_SIZE));
      for (let fx = 0; fx < TEMPLATE_SIZE; fx++) {
        const x0 = left + Math.floor(fx * bw / TEMPLATE_SIZE);
        const x1 = Math.max(x0 + 1, left + Math.floor((fx + 1) * bw / TEMPLATE_SIZE));
        let sum = 0, tot = 0;
        for (let y = y0; y < y1; y++) for (let x = x0; x < x1; x++) { sum += mask[y*w + x]; tot++; }
        cells[fy*TEMPLATE_SIZE + fx] = tot ? sum / tot : 0;
      }
    }
    return { cells, relH: bh / ch, relW: bw / cw };
  }

  function correlation(a, b, mirror) {
    const size = TEMPLATE_SIZE;
    let meanA = 0, meanB = 0;
    for (let i = 0; i < a.length; i++) { meanA += a[i]; meanB += b[i]; }
    meanA /= a.length; meanB /= b.length;
    let dot = 0, nA = 0, nB = 0;
    for (let y = 0; y < size; y++) for (let x = 0; x < size; x++) {
      const va = a[y*size + (mirror ? size-1-x : x)] - meanA;
      const vb = b[y*size + x] - meanB;
      dot += va*vb; nA += va*va; nB += vb*vb;
    }
    return dot / Math.sqrt(nA * nB + 1e-9);
  }

  // color = 'white' | 'black' -> each colour has its own template bank (black glyphs are drawn smaller/differently)
  function classify(feature, color) {
    const banks = BANKS[color];
    const scores = {};
    for (const bank of banks) {
      for (const type in bank) {
        const tp = bank[type];
        const shape = Math.max(correlation(feature.cells, tp.cells, false), correlation(feature.cells, tp.cells, true));
        const s = shape - LAMBDA * (Math.abs(feature.relH - tp.h) + Math.abs(feature.relW - tp.w));
        if (scores[type] === undefined || s > scores[type]) scores[type] = s;
      }
    }
    let best = 'p', bs = -Infinity, second = -Infinity;
    for (const t in scores) {
      if (scores[t] > bs) { second = bs; bs = scores[t]; best = t; }
      else if (scores[t] > second) second = scores[t];
    }
    return { type: best, margin: bs - second };
  }

  // Reads one board -> { pieces[64], unsure:Set }
  function readBoard(data, W, board, color) {
    const pieces = Array(64).fill('');
    const unsure = new Set();
    for (let row = 0; row < 8; row++) {
      for (let col = 0; col < 8; col++) {
        const sq = squareMask(data, W, board, row, col);
        if (!sq || sq.count < sq.w * sq.h * 0.05) continue;
        const f = buildFeature(sq);
        if (!f || f.relH < 0.35 * 0.8) continue;   // too short to be a piece -> noise
        const c = classify(f, color);
        const idx = row * 8 + col;
        pieces[idx] = color === 'white' ? c.type.toUpperCase() : c.type;
        if (c.margin < 0.06) unsure.add(idx);
      }
    }
    return { pieces, unsure };
  }
  // ===== CV END =====

  // --- Processing batches ---
  const unsureColor = { white: Array.from({ length: NB }, () => new Set()), black: Array.from({ length: NB }, () => new Set()) };
  const unsure = Array.from({ length: NB }, () => new Set());

  function imageToData(img) {
    const W = img.naturalWidth || img.width;
    const H = img.naturalHeight || img.height;
    const cv = document.createElement('canvas');
    cv.width = W; cv.height = H;
    const ctx = cv.getContext('2d', { willReadFrequently: true });
    ctx.drawImage(img, 0, 0);
    return { cv, data: ctx.getImageData(0, 0, W, H).data, W, H };
  }

  function drawCrop(src, board, target) {
    const pad = board ? board.w * 0.12 : 0;
    const sx = board ? Math.max(0, board.x - pad) : 0;
    const sy = board ? Math.max(0, board.y - pad) : 0;
    const sw = board ? Math.min(src.width - sx, board.w + 2 * pad) : src.width;
    const sh = board ? Math.min(src.height - sy, board.h + 2 * pad) : src.height;
    target.getContext('2d').drawImage(src, sx, sy, sw, sh, 0, 0, target.width, target.height);
  }

  function applyBoard(color, bombIdx, data, W, board) {
    const res = board ? readBoard(data, W, board, color) : { pieces: Array(64).fill(''), unsure: new Set() };
    boards[color][bombIdx] = res.pieces;
    unsureColor[color][bombIdx] = res.unsure;
    mergeBoards(bombIdx);
    return res.pieces.filter(Boolean).length;
  }

  // Auto-detects the boards (any scale/layout). Falls back to equal slices only if it does not find exactly 5.
  function locateBoards(data, W, H, color) {
    const found = findBoards(data, W, H);
    if (found.length === NB) return { boards: found, fallback: false };
    const rects = [];
    if (color === 'white') {
      for (let r = 0; r < 2; r++) for (let c = 0; c < 3; c++) {
        if (r * 3 + c === 5) continue;
        rects.push({ x0: Math.floor(c * W / 3), y0: Math.floor(r * H / 2), x1: Math.floor((c + 1) * W / 3), y1: Math.floor((r + 1) * H / 2) });
      }
    } else {
      for (let r = 0; r < NB; r++) rects.push({ x0: 0, y0: Math.floor(r * H / NB), x1: W, y1: Math.floor((r + 1) * H / NB) });
    }
    return { boards: rects.map(rc => findBoards(data, W, H, rc)[0] || null), fallback: true, foundCount: found.length };
  }

  function processBatch(img, color) {
    const { cv, data, W, H } = imageToData(img);
    const loc = locateBoards(data, W, H, color);
    const container = $(color === 'white' ? 'previewWhite' : 'previewBlack');
    container.innerHTML = '';
    const counts = [];
    for (let i = 0; i < NB; i++) {
      const board = loc.boards[i];
      counts.push(applyBoard(color, i, data, W, board));
      const thumb = $(`t${color}${i}`);
      if (thumb && board) drawCrop(cv, board, thumb);
      const p = document.createElement('canvas');
      p.width = 54; p.height = 54;
      if (board) drawCrop(cv, board, p);
      container.appendChild(p);
    }
    const name = color === 'white' ? 'White' : 'Black';
    $('batchStatus').textContent = loc.fallback
      ? `${name} batch: found ${loc.foundCount} boards (expected 5) – used fallback layout ⚠ · pieces ${counts.join('/')}`
      : `${name} batch: 5 boards found ✓ · pieces per board ${counts.join('/')}`;
    refreshAllUI();
    clearTimeout(batchTimer);
    batchTimer = setTimeout(() => {
      // If at least one bomb has both kings, auto-analyze
      const ready = boards.merged.some(b => b.filter(p => p === 'K').length === 1 && b.filter(p => p === 'k').length === 1);
      if (ready) analyzeAll();
    }, 300);
  }

  let batchTimer = 0;
  function processWhiteBatch(img) { processBatch(img, 'white'); }
  function processBlackBatch(img) { processBatch(img, 'black'); }

  function routeImage(img, forcedTarget) {
    const aspect = (img.naturalHeight || img.height) / (img.naturalWidth || img.width);
    if (forcedTarget === 'white') return processWhiteBatch(img);
    if (forcedTarget === 'black') return processBlackBatch(img);
    if (aspect >= 2.5) processBlackBatch(img); else processWhiteBatch(img);
  }

  // --- Board Merging & FEN Logic ---
  function mergeBoards(bombIdx) {
    conflicts[bombIdx].clear();
    for (let i = 0; i < 64; i++) {
      const wP = boards.white[bombIdx][i];
      const bP = boards.black[bombIdx][i];
      if (wP && bP) conflicts[bombIdx].add(i);
      boards.merged[bombIdx][i] = wP || bP;
    }
    unsure[bombIdx] = new Set([...unsureColor.white[bombIdx], ...unsureColor.black[bombIdx]]);
    const stat = $(`statcard${bombIdx}`);
    if (stat) stat.textContent = `W${boards.white[bombIdx].filter(Boolean).length} · B${boards.black[bombIdx].filter(Boolean).length}`;
    if (bombIdx === activeBomb) {
      renderBoard();
      updateFenInput();
    }
    updateBombCardPill(bombIdx);
  }

  function toFen(bombIdx, side = 'w') {
    const boardState = boards.merged[bombIdx];
    const ranks = [];
    for (let row = 0; row < 8; row++) {
      let text = '';
      let empty = 0;
      for (let col = 0; col < 8; col++) {
        const piece = boardState[row * 8 + col];
        if (!piece) { empty++; continue; }
        if (empty) text += empty;
        empty = 0;
        text += piece;
      }
      if (empty) text += empty;
      ranks.push(text);
    }
    return ranks.join('/') + (side === 'b' ? ' b' : ' w') + ' - - 0 1';
  }

  function updateFenInput() {
    $('fen').value = toFen(activeBomb);
  }

  function loadFen() {
    const fields = $('fen').value.trim().split(/\s+/);
    const placement = fields[0] || '';
    const rows = placement.split('/');
    if (rows.length !== 8) return;
    const targetBoard = boards.merged[activeBomb];
    rows.forEach((text, row) => {
      let col = 0;
      for (const ch of text) {
        if (/\d/.test(ch)) {
          for (let k = 0; k < Number(ch); k++) targetBoard[row * 8 + col++] = '';
        } else {
          targetBoard[row * 8 + col++] = ch;
        }
      }
    });
    conflicts[activeBomb].clear();
    unsure[activeBomb].clear();
    renderBoard();
    updateFenInput();
    updateBombCardPill(activeBomb);
  }

  // --- Rendering UI Elements ---
  function renderBoard() {
    const container = $('board');
    container.innerHTML = '';
    const boardState = boards.merged[activeBomb];
    const activeConflicts = conflicts[activeBomb];

    for (let i = 0; i < 64; i++) {
      const row = Math.floor(i / 8);
      const col = i % 8;
      const square = document.createElement('div');
      square.className = 'sq ' + ((row + col) % 2 === 0 ? 'light' : 'dark');
      if (activeConflicts.has(i)) square.classList.add('conflict');
      if (unsure[activeBomb].has(i)) square.classList.add('unsure');
      if (boardState[i] && boardState[i] === boardState[i].toUpperCase()) square.classList.add('white-piece');
      square.textContent = boardState[i] ? SHOWN[boardState[i]] : '';
      square.addEventListener('click', () => {
        boardState[i] = CYCLE[(CYCLE.indexOf(boardState[i]) + 1) % CYCLE.length];
        activeConflicts.delete(i);
        unsure[activeBomb].delete(i);
        renderBoard();
        updateFenInput();
        updateBombCardPill(activeBomb);
      });
      container.appendChild(square);
    }
  }

  function buildCardsAndTabs() {
    const bGrid = $('bGrid');
    const bTabs = $('bombTabs');
    bGrid.innerHTML = '';
    bTabs.innerHTML = '';

    for (let i = 0; i < NB; i++) {
      // Bomb Card
      const card = document.createElement('div');
      card.className = 'bombcard' + (i === activeBomb ? ' active' : '');
      card.id = `bombcard${i}`;
      card.innerHTML = `
        <div class="bhead">
          <span class="btitle">BOMB ${i + 1}</span>
          <span class="stat" id="statcard${i}"></span>
        </div>
        <div class="bthumbs">
          <div class="thumbbox">
            <label>White</label>
            <canvas id="twhite${i}" width="56" height="56"></canvas>
          </div>
          <div class="thumbbox">
            <label>Black</label>
            <canvas id="tblack${i}" width="56" height="56"></canvas>
          </div>
        </div>
        <div class="bpill bad" id="bpill${i}">Ans ${i + 1}: —</div>
      `;
      card.addEventListener('click', () => setActiveBomb(i));
      bGrid.appendChild(card);

      // Bomb Tab
      const tab = document.createElement('button');
      tab.className = 'tabbtn' + (i === activeBomb ? ' active' : '');
      tab.id = `tabbtn${i}`;
      tab.textContent = `BOMB ${i + 1}`;
      tab.addEventListener('click', () => setActiveBomb(i));
      bTabs.appendChild(tab);
    }
  }

  function setActiveBomb(i) {
    activeBomb = i;
    for (let k = 0; k < NB; k++) {
      $(`bombcard${k}`).classList.toggle('active', k === i);
      $(`tabbtn${k}`).classList.toggle('active', k === i);
    }
    renderBoard();
    updateFenInput();
  }

  // The answer for one bomb when it is clear which side: the one clicked, or the only side that can move
  function chosenSide(i) {
    if (picked[i]) return picked[i];
    const possible = ['w', 'b'].filter(sd => !answers[sd][i].impossible);
    return possible.length === 1 ? possible[0] : null;
  }
  function answerLine(i) {
    const sd = chosenSide(i);
    if (sd) return `Ans ${i + 1} : ${answers[sd][i].ok ? answers[sd][i].san : ''}`;
    const w = answers.w[i], b = answers.b[i];
    return `Ans ${i + 1} : ${w.ok || b.ok ? `${SIDE_ICON.w} ${w.ok ? w.san : '—'} / ${SIDE_ICON.b} ${b.ok ? b.san : '—'}` : ''}`;
  }
  const allLines = () => Array.from({ length: NB }, (_, i) => answerLine(i));
  const reportLines = () => { if (onSolved) onSolved(allLines()); };

  function updateBombCardPill(i) {
    const pill = $(`bpill${i}`);
    if (!pill) return;
    const w = answers.w[i], b = answers.b[i];
    const sd = picked[i];
    if (sd ? answers[sd][i].ok : (w.ok || b.ok)) {
      pill.textContent = sd
        ? `Ans ${i + 1}: ${SIDE_ICON[sd]} ${answers[sd][i].san}`
        : `Ans ${i + 1}: ${SIDE_ICON.w} ${w.ok ? w.san : '—'} · ${SIDE_ICON.b} ${b.ok ? b.san : '—'}`;
      pill.classList.remove('bad');
    } else {
      pill.textContent = `Ans ${i + 1}: —`;
      pill.classList.add('bad');
    }
  }

  // one half of an answer row: that side's best move (click = copy it and use it for COPY ALL)
  function sideHtml(i, sd) {
    const a = answers[sd][i];
    const body = a.ok
      ? `<span class="aside-move">${a.san}</span><span class="aside-uci">${a.uci}</span>`
      : `<span class="aside-none">${a.san && a.san.startsWith('⚠') ? a.san : '(not solved yet)'}</span>`;
    return `
      <div class="aside ${sd}${picked[i] === sd ? ' picked' : ''}${a.ok ? '' : ' empty'}" id="aside${sd}${i}" role="button" tabindex="0" title="Click to copy">
        <div class="aside-lab"><span>${SIDE_ICON[sd]} ${SIDE_NAME[sd].toUpperCase()} TO MOVE</span><span class="aside-hint">${picked[i] === sd ? 'COPIED ✓' : a.ok ? 'CLICK TO COPY' : ''}</span></div>
        <div class="aside-ans">${body}</div>
        ${a.uci ? `<div class="aside-foot"><span></span><button class="ghost aside-ucibtn" id="uci${sd}${i}">Copy UCI</button></div>` : ''}
      </div>`;
  }

  function buildAnswersSummary() {
    const list = $('aList');
    list.innerHTML = '';
    for (let i = 0; i < NB; i++) {
      const row = document.createElement('div');
      row.className = 'arow';
      row.innerHTML = `<span class="alab">Ans ${i + 1} :</span><div class="aduo">${sideHtml(i, 'w')}${sideHtml(i, 'b')}</div>`;
      for (const sd of ['w', 'b']) {
        const a = answers[sd][i];
        const half = row.querySelector(`#aside${sd}${i}`);
        const take = () => {
          if (!a.ok) return;
          copyText(a.san);
          picked[i] = sd;
          toast(`Copied Ans ${i + 1}: ${SIDE_NAME[sd]} ${a.san}`);
          updateBombCardPill(i);
          buildAnswersSummary();
          reportLines();
        };
        half.onclick = take;
        half.onkeydown = e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); take(); } };
        const ub = row.querySelector(`#uci${sd}${i}`);
        if (ub) ub.onclick = e => { e.stopPropagation(); copyText(a.uci); toast(`Copied Ans ${i + 1} UCI (${SIDE_NAME[sd]})`); };
      }
      list.appendChild(row);
    }
  }

  function refreshAllUI() {
    renderBoard();
    updateFenInput();
    for (let i = 0; i < NB; i++) updateBombCardPill(i);
    buildAnswersSummary();
  }

  // --- Stockfish (shared with the Chess module) ---
  const onEngineStatus = (text) => { if (!destroyed) $('engineStatus').textContent = text; };
  const startEngine = () => startSharedEngine(onEngineStatus);
  const OWNER = 'chess63';
  const askEngine = (fen, ms, onInfo) => askSharedEngine(fen, ms, onInfo, OWNER, { settle: true });
  // Each ANALYZE ALL run has a number; a newer run (another batch picture, or the button) replaces
  // the older one, which stops writing answers
  let runId = 0;

  async function analyzeBomb(i, thinkMs, run) {
    for (const sd of ['w', 'b']) {
      if (run !== runId || destroyed) return;
      await analyzeSide(i, sd, thinkMs, run);
    }
  }

  async function analyzeSide(i, side, thinkMs, run) {
    const fen = toFen(i, side);
    const bState = boards.merged[i];
    const whiteKings = bState.filter(p => p === 'K').length;
    const blackKings = bState.filter(p => p === 'k').length;

    if (whiteKings !== 1 || blackKings !== 1) {
      answers[side][i] = { san: '⚠ King missing', uci: '', ok: false };
      updateBombCardPill(i);
      buildAnswersSummary();
      return;
    }

    // the side not to move can't be in check
    const other = side === 'w' ? 'b' : 'w';
    if (kingInCheck(bState, other)) {
      answers[side][i] = { san: `⚠ not possible — ${SIDE_NAME[other]} is in check`, uci: '', ok: false, impossible: true };
      updateBombCardPill(i);
      buildAnswersSummary();
      return;
    }

    const cnt = p => bState.filter(x => x === p).length;
    const badPawn = bState.some((p, idx) => (p === 'P' || p === 'p') && (idx < 8 || idx >= 56));
    if (cnt('P') > 8 || cnt('p') > 8 || badPawn) {
      answers[side][i] = { san: '⚠ Bad Pawns', uci: '', ok: false };
      updateBombCardPill(i);
      buildAnswersSummary();
      return;
    }

    if (typeof window.Chess !== 'undefined') {
      const check = new window.Chess().validate_fen(fen);
      if (!check.valid) {
        answers[side][i] = { san: '⚠ Invalid FEN', uci: '', ok: false };
        updateBombCardPill(i);
        buildAnswersSummary();
        return;
      }
    }

    const uci = await askEngine(fen, thinkMs, ({ depth, cp, mate }) => {
      if (run === runId) $('engineStatus').textContent = `Bomb ${i + 1} (${SIDE_NAME[side]} to move) thinking… depth ${depth} · ` + (mate ? `mate in ${mate}` : `eval ${(Number(cp) / 100).toFixed(2)}`);
    });
    if (uci === SUPERSEDED || run !== runId || destroyed) return; // a newer run took over
    // the move must be legal on this board (an answer from another search is never shown)
    const san = uci && uci !== '(none)' ? legalSan(fen, uci) : null;
    answers[side][i] = san
      ? { san, uci, ok: true }
      : { san: uci === null ? '⚠ Engine unavailable / timed out' : uci === '(none)' ? '⚠ No legal move' : '⚠ Engine answer did not fit — ANALYZE again', uci: '', ok: false };
    updateBombCardPill(i);
    buildAnswersSummary();
  }

  async function analyzeAll() {
    const run = ++runId;
    if (!(await startEngine())) return;
    const thinkMs = Number($('thinkTime').value);
    for (let i = 0; i < NB; i++) {
      if (run !== runId || destroyed) return;
      $('engineStatus').textContent = `Analyzing Bomb ${i + 1} / ${NB}…`;
      await analyzeBomb(i, thinkMs, run);
    }
    if (run !== runId || destroyed) return;
    $('engineStatus').textContent = 'Done! Solved all 5 bombs for White and Black ✓ — click the side each bomb asks for';
    reportLines();
  }

  // --- Event Handlers & Drag & Drop ---
  $('fileWhite').addEventListener('change', async e => {
    if (e.target.files[0]) routeImage(await loadImg(e.target.files[0]), 'white');
    e.target.value = '';
  });

  $('fileBlack').addEventListener('change', async e => {
    if (e.target.files[0]) routeImage(await loadImg(e.target.files[0]), 'black');
    e.target.value = '';
  });

  // Drag & drop. A screenshot dragged from Discord is a link, not a file, so both go through the
  // app's image loader; a drop anywhere else on the page is routed by its shape like a paste.
  const visible = () => !destroyed && root.offsetParent !== null;
  // dragging something that is already on this page (a thumbnail, selected text): not a new image
  const droppable = dt => Boolean(dt) && (Array.from(dt.types || []).includes('Files') || !isInternalDrag(dt));
  const dropStatus = text => { const el = $('batchStatus'); if (el) el.textContent = text; };
  const dropSource = (dt, target) => {
    const src = extractImageSource(dt);
    if (!src) { dropStatus('Drop an image file or an image link.'); return; }
    if (src.type === 'url') dropStatus('Downloading image…');
    loadSource(src, target);
  };
  const setupDropzone = (el, targetColor) => {
    const on = e => {
      if (!droppable(e.dataTransfer)) return;
      e.preventDefault();
      if (e.dataTransfer) e.dataTransfer.dropEffect = 'copy';
      el.classList.add('active');
    };
    el.addEventListener('dragenter', on);
    el.addEventListener('dragover', on);
    el.addEventListener('dragleave', e => { if (!el.contains(e.relatedTarget)) el.classList.remove('active'); });
    el.addEventListener('drop', e => {
      el.classList.remove('active');
      if (!droppable(e.dataTransfer)) return;
      e.preventDefault(); // also tells the page-wide handler below that this drop is taken
      dropSource(e.dataTransfer, targetColor);
    });
  };
  setupDropzone($('zoneWhite'), 'white');
  setupDropzone($('zoneBlack'), 'black');

  const onWinEnter = e => {
    if (!visible()) return;
    if (dragHasLink(e.dataTransfer)) warmImageHosts(); // start the Discord connection early
    if (droppable(e.dataTransfer)) e.preventDefault();
  };
  const onWinOver = e => {
    if (!visible() || !droppable(e.dataTransfer)) return;
    e.preventDefault(); // without this the browser opens the dropped image instead
    if (e.dataTransfer) e.dataTransfer.dropEffect = 'copy';
  };
  const onWinDrop = e => {
    if (!visible()) return;
    const ok = droppable(e.dataTransfer);
    if (!ok || e.defaultPrevented) return;
    e.preventDefault();
    dropSource(e.dataTransfer); // tall strip → Black, otherwise White
  };
  window.addEventListener('dragenter', onWinEnter);
  window.addEventListener('dragover', onWinOver);
  window.addEventListener('drop', onWinDrop);

  // Ctrl+V anywhere while this view is on screen (outside text boxes): image, or an image link
  const onPaste = e => {
    if (destroyed || root.offsetParent === null) return;
    const a = document.activeElement;
    if (a && (a.tagName === 'TEXTAREA' || (a.tagName === 'INPUT' && a.type === 'text') || a.isContentEditable)) return;
    const src = extractImageFromPaste(e.clipboardData);
    if (!src) return;
    e.preventDefault();
    e.stopImmediatePropagation();
    loadSource(src);
  };
  document.addEventListener('paste', onPaste, true);

  $('loadFen').addEventListener('click', loadFen);
  $('clearBoard').addEventListener('click', () => {
    boards.merged[activeBomb].fill('');
    boards.white[activeBomb].fill('');
    boards.black[activeBomb].fill('');
    conflicts[activeBomb].clear();
    unsure[activeBomb].clear();
    renderBoard();
    updateFenInput();
    updateBombCardPill(activeBomb);
  });

  $('analyzeAll').addEventListener('click', analyzeAll);
  $('copyAll').addEventListener('click', () => {
    copyText(allLines().join('\n'));
    toast(picked.every(Boolean) ? 'Copied all 5 answers!' : 'Copied — bombs with no side clicked show both moves');
  });

  // Initialization
  buildCardsAndTabs();
  renderBoard();
  updateFenInput();
  buildAnswersSummary();
  const idle = (window.requestIdleCallback || setTimeout)(startEngine);

  // an image from the phone paste box / a link: same routing as a pasted screenshot
  function loadSource(src, target) {
    loadImageSource(src, img => { if (!destroyed) routeImage(img, target); },
      msg => { $('batchStatus').textContent = msg || 'Could not load that image'; });
  }

  return {
    loadSource,
    destroy() {
      destroyed = true;
      document.removeEventListener('paste', onPaste, true);
      window.removeEventListener('dragenter', onWinEnter);
      window.removeEventListener('dragover', onWinOver);
      window.removeEventListener('drop', onWinDrop);
      clearTimeout(batchTimer);
      try { (window.cancelIdleCallback || clearTimeout)(idle); } catch (e) {}
      cancelSearch(OWNER); // the engine is shared: stop this solver's search, keep the worker
      stopEngineListener(onEngineStatus);
    }
  };
}
